import java.nio.file.*;import java.util.*;import java.util.zip.*;import org.objectweb.asm.*;import org.objectweb.asm.tree.*;import org.objectweb.asm.tree.analysis.*;
public class Patch implements Opcodes {
 static final String ROOT="dev/zomboid/remains/ZombieRemainsLoot",H="dev/zomboid/remains/expand/ExpandedBodies";
 static AbstractInsnNode next(AbstractInsnNode n){do{n=n.getNext();}while(n!=null&&n.getOpcode()<0);return n;}static AbstractInsnNode prev(AbstractInsnNode n){do{n=n.getPrevious();}while(n!=null&&n.getOpcode()<0);return n;}
 public static void main(String[] args)throws Exception{Map<String,byte[]> data=new TreeMap<>();int install=0,load=0,save=0,menu=0,methods=0;try(ZipFile z=new ZipFile(args[0])){for(var es=z.entries();es.hasMoreElements();){var e=es.nextElement();byte[] b=z.getInputStream(e).readAllBytes();if(Set.of(ROOT+".class",ROOT+"$Corpse.class",ROOT+"$CorpseData.class").contains(e.getName())){ClassNode c=new ClassNode();new ClassReader(b).accept(c,0);
 if(c.name.equals(ROOT+"$Corpse")){for(FieldNode f:c.fields)if(f.name.equals("inventory"))f.access&=~ACC_FINAL;for(MethodNode m:c.methods)if(m.name.equals("<init>")&&Type.getArgumentTypes(m.desc).length==3)for(AbstractInsnNode n:m.instructions.toArray())if(n.getOpcode()==RETURN){InsnList h=new InsnList();h.add(new VarInsnNode(ALOAD,0));h.add(new VarInsnNode(ALOAD,1));h.add(new MethodInsnNode(INVOKESTATIC,H,"install","(Ljava/lang/Object;Ljava/lang/Object;)V",false));m.instructions.insertBefore(n,h);install++;}}
 if(c.name.equals(ROOT+"$CorpseData"))for(MethodNode m:c.methods){if(m.name.equals("load")){int tag=-1;for(AbstractInsnNode n:m.instructions.toArray()){if(n instanceof MethodInsnNode call&&call.name.equals("getCompound")&&next(n) instanceof VarInsnNode store&&store.getOpcode()==ASTORE)tag=store.var;if(n instanceof MethodInsnNode call&&call.owner.equals(ROOT+"$Corpse")&&call.name.equals("<init>")){AbstractInsnNode after=next(n);if(!(after instanceof VarInsnNode store)||store.getOpcode()!=ASTORE||tag<0)throw new IllegalStateException("corpse load locals");InsnList h=new InsnList();h.add(new VarInsnNode(ALOAD,store.var));h.add(new VarInsnNode(ALOAD,tag));h.add(new MethodInsnNode(INVOKESTATIC,H,"restore","(Ljava/lang/Object;Ljava/lang/Object;)V",false));m.instructions.insert(after,h);load++;}}}if(m.name.equals("save"))for(AbstractInsnNode n:m.instructions.toArray())if(n instanceof MethodInsnNode call&&call.name.equals("putString")&&prev(n) instanceof FieldInsnNode field&&field.owner.equals(ROOT+"$Corpse")&&field.name.equals("block")){AbstractInsnNode corpse=prev(field),key=prev(corpse),tag=prev(key);if(!(corpse instanceof VarInsnNode a)||!(key instanceof LdcInsnNode literal)||!literal.cst.equals("Block")||!(tag instanceof VarInsnNode t))throw new IllegalStateException("corpse save locals");InsnList h=new InsnList();h.add(new VarInsnNode(ALOAD,a.var));h.add(new VarInsnNode(ALOAD,t.var));h.add(new MethodInsnNode(INVOKESTATIC,H,"saveSize","(Ljava/lang/Object;Ljava/lang/Object;)V",false));m.instructions.insert(n,h);save++;}}
 if(c.name.equals(ROOT))for(MethodNode m:c.methods)if(m.name.startsWith("lambda$")&&Type.getReturnType(m.desc).getInternalName().equals("net/minecraft/world/inventory/AbstractContainerMenu")){Type[] types=Type.getArgumentTypes(m.desc);if(types.length!=7||types[4].getSort()!=Type.INT)throw new IllegalStateException(m.desc);m.instructions.clear();m.tryCatchBlocks.clear();m.localVariables=null;int local=0;for(Type t:types){m.instructions.add(new VarInsnNode(t.getOpcode(ILOAD),local));local+=t.getSize();}m.instructions.add(new MethodInsnNode(INVOKESTATIC,H,"menu","(Ljava/lang/Object;Ljava/lang/Object;Ljava/lang/Object;Ljava/lang/Object;ILjava/lang/Object;Ljava/lang/Object;)Ljava/lang/Object;",false));m.instructions.add(new TypeInsnNode(CHECKCAST,"net/minecraft/world/inventory/AbstractContainerMenu"));m.instructions.add(new InsnNode(ARETURN));m.maxLocals=local;menu++;}
 ClassWriter w=new ClassWriter(ClassWriter.COMPUTE_MAXS);c.accept(w);b=w.toByteArray();}data.put(e.getName(),b);}}
 if(install!=1||load!=1||save!=1||menu!=1)throw new IllegalStateException("hooks: "+install+","+load+","+save+","+menu);
 try(var f=Files.walk(Path.of(args[2]))){for(var p:f.filter(p->p.toString().endsWith(".class")).toList()){String n=Path.of(args[2]).relativize(p).toString();if(n.startsWith("dev/zomboid/remains/expand/"))data.put(n,Files.readAllBytes(p));}}
 for(var e:data.entrySet())if(e.getKey().endsWith(".class")){ClassNode c=new ClassNode();new ClassReader(e.getValue()).accept(c,0);for(var m:c.methods)if((m.access&(ACC_ABSTRACT|ACC_NATIVE))==0){new Analyzer<BasicValue>(new BasicVerifier()).analyze(c.name,m);methods++;}}
 try(var z=new ZipOutputStream(Files.newOutputStream(Path.of(args[1])))){for(var e:data.entrySet()){z.putNextEntry(new ZipEntry(e.getKey()));z.write(e.getValue());z.closeEntry();}}
 System.out.println("Install/load/save/menu hooks: 4; verified methods: "+methods);
 }
}
